  <style>
    :root {
      --mondrian-black: #111111;
      --mondrian-white: #FFFFFF;
      --mondrian-paper: #F6F4EE;
      --mondrian-grey: #DCD9D0;
      --mondrian-red: #C81E1E;
      --mondrian-blue: #143C8C;
      --mondrian-yellow: #F4C400;
      --line-thick: 8px;
      --line-thin: 4px;
      --font-sans: 'Space Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --font-mono: 'IBM Plex Mono', monospace;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    html {
      scroll-behavior: smooth;
      background-color: var(--mondrian-black);
      color: var(--mondrian-black);
      font-family: var(--font-sans);
      line-height: 1.5;
    }

    body {
      max-width: 1440px;
      margin: 0 auto;
      background-color: var(--mondrian-black);
      border-left: var(--line-thick) solid var(--mondrian-black);
      border-right: var(--line-thick) solid var(--mondrian-black);
    }

    a { color: inherit; text-decoration: underline; text-underline-offset: 4px; }
    a:focus-visible, button:focus-visible { outline: 4px solid var(--mondrian-yellow); outline-offset: 2px; }

    .mondrian-grid {
      display: grid;
      background-color: var(--mondrian-black);
      gap: var(--line-thick);
      border-top: var(--line-thick) solid var(--mondrian-black);
    }

    .cell-white { background-color: var(--mondrian-white); color: var(--mondrian-black); }
    .cell-paper { background-color: var(--mondrian-paper); color: var(--mondrian-black); }
    .cell-grey { background-color: var(--mondrian-grey); color: var(--mondrian-black); }
    .cell-red { background-color: var(--mondrian-red); color: var(--mondrian-white); }
    .cell-blue { background-color: var(--mondrian-blue); color: var(--mondrian-white); }
    .cell-yellow { background-color: var(--mondrian-yellow); color: var(--mondrian-black); }
    .cell-black { background-color: var(--mondrian-black); color: var(--mondrian-white); }

    .pad-sm { padding: 1.15rem 1.35rem; }
    .pad-md { padding: 2rem; }
    .pad-lg { padding: 2.85rem 2.5rem; }

    .mono-label {
      font-family: var(--font-mono);
      font-size: 0.78rem;
      font-weight: 600;
      letter-spacing: 0.09em;
      text-transform: uppercase;
      display: inline-block;
    }

    .top-nav { grid-template-columns: 200px 1fr auto auto; }
    .brand-mark {
      display: flex;
      align-items: center;
      font-family: var(--font-mono);
      font-weight: 600;
      font-size: 0.85rem;
      text-decoration: none;
      letter-spacing: 0.06em;
    }

    .nav-links {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 1.5rem;
      list-style: none;
    }

    .nav-links a {
      text-decoration: none;
      font-weight: 700;
      font-size: 0.9rem;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .nav-links a:hover { text-decoration: underline; }

    .hero-grid { grid-template-columns: 7fr 5fr; min-height: 640px; }
    .hero-left {
      display: grid;
      grid-template-rows: 1fr auto;
      gap: var(--line-thick);
      background-color: var(--mondrian-black);
    }

